/* From Uiverse.io by TanimMahbub  - Tags: simple, tooltip, icon, black */
.__UIV_SCOPE__ .wrapper {
  display: flex;
  gap: 10px;
  font-family: monospace;
}

.__UIV_SCOPE__ .wrapper > div {
  text-align: center;
}

.__UIV_SCOPE__ .wrapper > div + div {
  border-inline-start: 1px solid #d6cfcf;
  padding-inline-start: 15px;
}

.__UIV_SCOPE__ .wrapper > div > p {
  margin-top: 15px;
  max-width: 200px;
}

.__UIV_SCOPE__ .wrapper a {
  display: inline-flex;
  width: 50px;
  height: 50px;
  border-radius: 100%;
  justify-content: center;
  align-items: center;
  background-color: #191919;
  color: #d5ad72;
  position: relative;
}

.__UIV_SCOPE__ .data-tooltip::before,
.__UIV_SCOPE__ .data-tooltip::after {
  position: absolute;
  visibility: hidden;
  opacity: 0;
  transform: translateY(5px);
  transition: all 0.2s ease;
}

.__UIV_SCOPE__ .data-tooltip::before {
  content: attr(data-tooltip-content);
  width: fit-content;
  font-size: small;
  font-weight: 600;
  background-color: inherit;
  padding: 3px 10px;
  border-radius: 4px;
  bottom: calc(100% + 5px);
}

.__UIV_SCOPE__ .data-tooltip::after {
  content: "";
  border-top: 5px solid #191919;
  border-left: 5px solid transparent;
  border-right: 5px solid transparent;
  bottom: calc(100% + 1px);
}

.__UIV_SCOPE__ .data-tooltip:hover::before,
.__UIV_SCOPE__ .data-tooltip:hover::after {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
}

.__UIV_SCOPE__ .span-tooltip > i {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .span-tooltip > span {
  position: absolute;
  width: fit-content;
  font-size: small;
  font-weight: 600;
  background-color: inherit;
  padding: 3px 10px;
  border-radius: 4px;
  bottom: 100%;
  visibility: hidden;
  opacity: 0;
  transition: all 0.2s ease;
}

.__UIV_SCOPE__ .span-tooltip > span::before {
  position: absolute;
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 3px;
  background-color: inherit;
  transform: rotate(45deg);
  top: calc(100% - 6px);
  left: 40%;
}

.__UIV_SCOPE__ .span-tooltip > i:hover + span {
  visibility: visible;
  opacity: 1;
  bottom: calc(100% + 6px);
}
